import { build } from 'esbuild';
import { fileURLToPath } from 'node:url';

export async function buildBrowserBundle(entryFile = 'app.js') {
  const result = await build({
    absWorkingDir: fileURLToPath(new URL('../', import.meta.url)),
    entryPoints: [entryFile],
    outfile: 'bundle.js',
    bundle: true,
    format: 'iife',
    platform: 'browser',
    target: 'es2022',
    charset: 'utf8',
    write: false,
    logLevel: 'silent',
    banner: { js: '// Generated by scripts/build-bundle.mjs. Do not edit directly.\n"use strict";' }
  });
  return result.outputFiles[0].text;
}
